package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Applies the edit: the grade is recorded from the from-date (the sheet's today when blank), replacing one recorded
 *  from the same date and keeping the others; a save leaving the grade as the row showed it (in force on the sheet's
 *  today) with the from-date blank records nothing.
 *  The person's own terms become the ones given (null: none), and their contact the one given (null: none), and their tags the ones given. */
public class ApplyPerson {
    public void apply(@Val Person person, @Val PersonValues values, SheetRepository sheets, Out<Person> changed,
            Out<TermsBefore> termsBefore, Out<ContactBefore> contactBefore) {
        termsBefore.set(new TermsBefore(person.terms()));
        contactBefore.set(new ContactBefore(person.contact()));
        changed.set(edited(person, values, sheets.today(person.sheetId())));
    }

    /** The person as the edit leaves them, on the sheet's today (see above). */
    static Person edited(Person person, PersonValues values, LocalDate today) {
        List<PersonGrade> grades = new ArrayList<>(person.grades());
        if (values.gradeFrom() != null || !values.grade().equals(person.grade())) {
            LocalDate from = values.gradeFrom() != null ? values.gradeFrom() : today;
            grades.removeIf((g) -> Objects.equals(g.from(), from));
            grades.add(new PersonGrade(values.grade(), from));
            grades.sort(Comparator.comparing(PersonGrade::from, Comparator.nullsFirst(Comparator.naturalOrder())));
        }
        List<PersonGrade> kept = List.copyOf(grades);
        return new Person(person.id(), person.sheetId(), values.name(), Person.gradeOn(kept, today), person.version() + 1,
                person.retiredFrom(), kept, person.holds(), values.terms(), values.contact(), person.aliases())
                .withRetirements(person.retirements()).withTags(values.tags());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.TreeSet;

/** A person's values once validated, and who gives them; for an edit, the version it was made from (null for an add).
 *  {@code gradeFrom} is the date the grade is given from, null when left blank; {@code terms} the person's own terms, a
 *  whole number of days 0 or more, null when left blank; {@code contact} the person's
 *  contact without surrounding spaces and lower-cased, null when left blank; {@code tags} the person's tags (see
 *  #tags). */
public record PersonValues(String name, String grade, String by, Long version, LocalDate gradeFrom, Integer terms, String contact,
        List<String> tags) {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** The request's values by the person form's rules (see ValidatePerson). */
    public static PersonValues from(PersonRequest request) throws InvalidPersonException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("Grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        LocalDate gradeFrom = null;
        if (!from.isEmpty()) {
            try {
                gradeFrom = LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date");
            }
        }
        String days = request.terms() == null ? "" : request.terms().trim();
        Integer terms = null;
        if (!days.isEmpty()) {
            if (!days.matches("[0-9]{1,6}")) {
                throw new InvalidPersonException("The terms must be a whole number of days, 0 or more");
            }
            terms = Integer.parseInt(days);
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        return new PersonValues(name, grade, request.by() == null ? "" : request.by().trim(), request.version(), gradeFrom,
                terms, contact.isEmpty() ? null : contact, tags(request.tags()));
    }

    /** Comma separated tags as kept: each trimmed and in lower case, blanks and repeats dropped, sorted. */
    public static List<String> tags(String typed) throws InvalidPersonException {
        if (typed == null) {
            return List.of();
        }
        List<String> tags = List.copyOf(new TreeSet<>(Arrays.stream(typed.split(",")).map((t) -> t.trim().toLowerCase(Locale.ROOT))
                .filter((t) -> !t.isEmpty()).toList()));
        if (String.join(",", tags).length() > 2000) {
            throw new InvalidPersonException("The tags are too long");
        }
        return tags;
    }
}
package net.officefloor.hq.app.person;

/** Body of an add or edit of a person, and who makes it. An edit carries the version of the person it was made from,
 *  and the date (yyyy-MM-dd) its grade is from: blank for the sheet's today. {@code terms} are the person's own terms in
 *  days, blank for none. {@code contact}
 *  is the person's contact, blank for none. {@code tags} are the person's tags, comma separated (null or blank: none). */
public record PersonRequest(String name, String grade, String by, Long version, String gradeFrom, String terms, String contact,
        String tags) {
